// Fusionne le lead (score + température de la règle) et la réponse de l'IA.
// categorie_ia = température de la règle (chaud/tiede/froid) ; repli IA en panne ou invalide = a_qualifier.
// resume_ia = "[thème] résumé" ; repli = "[autre] Analyse IA indisponible : lire le besoin."
const lead = $('Score (règle budget + délai)').item.json;
const themes = ['automatisation', 'agent IA', 'reporting', 'autre'];
// Nombres d'un texte : « 1 200 » → 1200, « 1,5 » → 1.5
const nombres = (t) => (String(t).replace(/(\d)[\s  .](?=\d{3}(?!\d))/g, '$1').replace(/(\d),(\d)/g, '$1.$2').match(/\d+(?:\.\d+)?/g) ?? []).map(Number);
// Périodes d'un texte ramenées à un radical : « par semaine » ≠ « semestriels »
const periodes = (t) => (String(t).toLowerCase().match(/semaine|hebdomadaire|jour|quotidien|mois|mensuel|trimestr|semestr|annuel|\ban(?:s|nées?)?\b|heure/g) ?? []).map((p) => ({ hebdomadaire: 'semaine', quotidien: 'jour', mensuel: 'mois', annuel: 'an' }[p] ?? p.replace(/^an.*/, 'an')));
let theme = 'autre';
let resume = 'Analyse IA indisponible : lire le besoin.';
let ia_ok = false;
let garde_fou = false;
try {
  const r = JSON.parse($json.message?.content ?? '');
  if (themes.includes(r.categorie) && typeof r.resume === 'string' && r.resume.trim()) {
    theme = r.categorie;
    resume = r.resume.trim().slice(0, 200);
    ia_ok = true;
  }
} catch (e) {}
// Garde-fou : tout nombre du résumé doit figurer dans l'entrée, sinon résumé fixe.
if (ia_ok) {
  const entree = nombres(`${lead.besoin} ${lead.budget} ${lead.delai}`);
  const periodesEntree = periodes(`${lead.besoin} ${lead.delai}`);
  if (nombres(resume).some((n) => !entree.includes(n)) || periodes(resume).some((p) => !periodesEntree.includes(p))) {
    garde_fou = true;
    theme = 'autre';
    resume = `Demande de ${lead.entreprise}, budget ${lead.budget}, délai ${lead.delai}`;
  }
}
return { json: { ...lead, theme, resume: `[${theme}] ${resume}`, categorie: ia_ok ? lead.score : 'a_qualifier', ia_ok, garde_fou } };
